// Writes the AI providers' logos for every client: gen/ts/providers.ts,
// gen/swift/ProviderLogos.xcassets with MavioProviderLogos.swift,
// gen/kotlin's ProviderLogos.kt and gen/go/providers.go, each looking a
// logo up by the provider's ID.
import { write } from './util.js';
import { KOTLIN_PACKAGE } from './emit-kotlin.js';

const json = (o) => JSON.stringify(o, null, 2);

// The first line of every generated file, in the comment syntax of its language.
const HEADER = (open) => `${open} Code generated by libs/design/build from libs/design/providers. DO NOT EDIT.`;

function ts({ logos, providers }) {
  return `${HEADER('//')}
/** An AI provider's logo: its SVG, and whether it draws in the text's color (currentColor) rather than its own. */
export interface ProviderLogo {
  readonly svg: string;
  readonly monochrome: boolean;
}

const logos: { readonly [name: string]: ProviderLogo } = ${json(logos)};

const providers: { readonly [id: string]: string } = ${json(providers)};

/** The logo of the AI provider with id, or undefined for one without. */
export function providerLogo(id: string): ProviderLogo | undefined {
  const name = providers[id];
  return name === undefined ? undefined : logos[name];
}
`;
}

// The asset of a logo: ProviderLogo + its name in PascalCase.
const asset = (name) => 'ProviderLogo' + name.split('-').map((s) => s.charAt(0).toUpperCase() + s.slice(1)).join('');

function swift({ logos, providers }) {
  const root = 'gen/swift/ProviderLogos.xcassets';
  write(`${root}/Contents.json`, json({ info: { author: 'xcode', version: 1 } }) + '\n');
  for (const [name, { svg, monochrome }] of Object.entries(logos)) {
    write(`${root}/${asset(name)}.imageset/${asset(name)}.svg`, svg + '\n');
    const properties = { 'preserves-vector-representation': true, 'template-rendering-intent': monochrome ? 'template' : 'original' };
    write(`${root}/${asset(name)}.imageset/Contents.json`, json({ images: [{ filename: `${asset(name)}.svg`, idiom: 'universal' }], info: { author: 'xcode', version: 1 }, properties }) + '\n');
  }
  return `${HEADER('//')}

/// The logos of the AI providers, images of ProviderLogos.xcassets in this package's bundle.
public enum MavioProviderLogos {
    /// The asset name of the logo of the AI provider with id, or nil for one without; monochrome logos render as templates.
    public static func assetName(for id: String) -> String? {
        switch id {
${Object.entries(providers).map(([id, name]) => `        case "${id}": "${asset(name)}"`).join('\n')}
        default: nil
        }
    }
}
`;
}

function kotlin({ logos, providers }) {
  const constName = (name) => name.toUpperCase().replace(/-/g, '_');
  return `${HEADER('//')}
package ${KOTLIN_PACKAGE}

/** An AI provider's logo: its SVG, and whether it draws in the text's color (currentColor) rather than its own. */
data class ProviderLogo(val svg: String, val monochrome: Boolean)

/** The logos of the AI providers, by provider ID. */
object ProviderLogos {
${Object.entries(logos).map(([name, { svg, monochrome }]) => `    private val ${constName(name)} = ProviderLogo(${JSON.stringify(svg)}, ${monochrome})`).join('\n')}

    /** The logo of the AI provider with [id], or null for one without. */
    fun of(id: String): ProviderLogo? =
        when (id) {
${Object.entries(providers).map(([id, name]) => `            "${id}" -> ${constName(name)}`).join('\n')}
            else -> null
        }
}
`;
}

function go({ logos, providers }) {
  const constName = (name) => 'logo' + name.split('-').map((s) => s.charAt(0).toUpperCase() + s.slice(1)).join('');
  return `${HEADER('//')}

package design

// ProviderLogo is an AI provider's logo: its SVG, and whether it draws in the
// text's color (currentColor) rather than its own.
type ProviderLogo struct {
	SVG        string
	Monochrome bool
}

const (
${Object.entries(logos).map(([name, { svg }]) => `\t${constName(name)} = ${JSON.stringify(svg)}`).join('\n')}
)

// ProviderLogoOf returns the logo of the AI provider with id, and false for
// one without.
func ProviderLogoOf(id string) (ProviderLogo, bool) {
	switch id {
${Object.entries(providers).map(([id, name]) => `\tcase "${id}":\n\t\treturn ProviderLogo{SVG: ${constName(name)}, Monochrome: ${logos[name].monochrome}}, true`).join('\n')}
	}
	return ProviderLogo{}, false
}
`;
}

export function emitProviders(p) {
  write('gen/ts/providers.ts', ts(p));
  write('gen/swift/MavioProviderLogos.swift', swift(p));
  write(`gen/kotlin/${KOTLIN_PACKAGE.replace(/\./g, '/')}/ProviderLogos.kt`, kotlin(p));
  write('gen/go/providers.go', go(p));
}
